class Solution {
  public int minimumBoxes(int n) {
    int layer = 0;
    long used = 0;
    while (used + (long) (layer + 1) * (layer + 2) / 2 <= n) {
      layer++;
      used += (long) layer * (layer + 1) / 2;
    }
    int base = layer * (layer + 1) / 2;
    int extra = 0;
    while (used < n) {
      extra++;
      used += extra;
    }
    return base + extra;
  }
}
